CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS classrooms (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, teacher_id BIGINT NOT NULL, name VARCHAR(190) NOT NULL, subject VARCHAR(190) NOT NULL, description TEXT NOT NULL, code VARCHAR(20) NOT NULL UNIQUE, student_ids JSONB NOT NULL DEFAULT '[]'::jsonb, quizzes JSONB NOT NULL DEFAULT '[]'::jsonb, announcements JSONB NOT NULL DEFAULT '[]'::jsonb, chat_messages JSONB NOT NULL DEFAULT '[]'::jsonb, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, student_id BIGINT NOT NULL, classroom_id BIGINT NOT NULL, quiz_id BIGINT NOT NULL, quiz_title VARCHAR(255) NOT NULL, game_type VARCHAR(100) NOT NULL, answers JSONB NOT NULL DEFAULT '[]'::jsonb, score INT NOT NULL, max_score INT NOT NULL, elapsed_seconds INT NOT NULL, played_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_classrooms_teacher_id ON classrooms (teacher_id);
CREATE INDEX IF NOT EXISTS idx_attempts_student_id ON attempts (student_id);
CREATE INDEX IF NOT EXISTS idx_attempts_classroom_id ON attempts (classroom_id);
CREATE INDEX IF NOT EXISTS idx_attempts_quiz_id ON attempts (quiz_id);
ALTER TABLE users ADD COLUMN IF NOT EXISTS account_status VARCHAR(20) NOT NULL DEFAULT 'active';
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT, target_id BIGINT, action VARCHAR(80) NOT NULL, occurred_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_logs_action ON audit_logs(action, id);
CREATE TABLE IF NOT EXISTS gradebooks (classroom_id BIGINT PRIMARY KEY REFERENCES classrooms(id) ON DELETE RESTRICT, data JSONB NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS grade_changes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, classroom_id BIGINT NOT NULL REFERENCES gradebooks(classroom_id) ON DELETE RESTRICT, student_id BIGINT REFERENCES users(id) ON DELETE RESTRICT, item_id VARCHAR(80), actor_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, action VARCHAR(80) NOT NULL, previous_value JSONB, new_value JSONB, created_at VARCHAR(40) NOT NULL);
CREATE INDEX IF NOT EXISTS idx_grade_changes_classroom ON grade_changes(classroom_id, id);
